<form method="POST" action="<?php echo e(route('admin.notifications.templates')); ?>" class="mt-4 grid gap-4 sm:grid-cols-2"><?php echo csrf_field(); ?> <?php echo method_field('PUT'); ?>
    <label class="text-sm">Event type<input name="event_type" value="<?php echo e($template?->event_type); ?>" required pattern="[a-z][a-z0-9_]{1,99}" placeholder="e.g. onboarding_reminder" class="mt-1 w-full rounded-xl border-slate-300"></label><label class="text-sm">Title<input name="title" value="<?php echo e($template?->title); ?>" required maxlength="255" class="mt-1 w-full rounded-xl border-slate-300"></label>
    <label class="text-sm sm:col-span-2">In-app message<textarea name="message" required maxlength="2000" rows="3" class="mt-1 w-full rounded-xl border-slate-300"><?php echo e($template?->message); ?></textarea></label>
    <label class="flex items-center gap-2 text-sm"><input type="hidden" name="enabled" value="0"><input type="checkbox" name="enabled" value="1" <?php if($template?->enabled??true): echo 'checked'; endif; ?>>Event enabled</label><div class="flex flex-wrap gap-4"><?php $__currentLoopData = ['email','push']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $channel): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label class="text-sm"><input type="checkbox" name="channels[]" value="<?php echo e($channel); ?>" <?php if(in_array($channel,$template?->channels??['email','push'])): echo 'checked'; endif; ?>><?php echo e(ucfirst($channel)); ?></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div><button class="acad-primary-button">Save event template</button>
</form>
